import re

_BASE = {
    "void": "None", "char": "c_char", "signed char": "c_byte", "unsigned char": "c_ubyte",
    "short": "c_short", "unsigned short": "c_ushort", "int": "c_int", "unsigned int": "c_uint", "unsigned": "c_uint",
    "long long": "c_longlong", "unsigned long long": "c_ulonglong", "float": "c_float", "double": "c_double",
    "bool": "c_bool", "size_t": "c_size_t", "wchar_t": "c_wchar",
    "int8_t": "c_int8", "uint8_t": "c_uint8", "int16_t": "c_int16", "uint16_t": "c_uint16",
    "int32_t": "c_int32", "uint32_t": "c_uint32", "int64_t": "c_int64", "uint64_t": "c_uint64",
}
_KEYWORDS = {"void", "char", "short", "int", "long", "unsigned", "signed", "float", "double", "bool", "const", "struct"}
_IDENT = re.compile(r"[A-Za-z_]\w*")
_STRUCT = re.compile(r"(typedef\s+)?struct\s+(\w+)?\s*\{(.*?)\}\s*(\w*)\s*;", re.S)


def _type(c_type, structs):
    words = [w for w in c_type.replace("*", " * ").split() if w != "const"]
    stars = 0
    while words and words[-1] == "*":
        words.pop()
        stars += 1
    if not words or "*" in words:
        raise ValueError(f"not a type: {c_type!r}")
    base = " ".join(words)
    if base in ("long", "unsigned long", "long int", "unsigned long int"):
        raise ValueError("long has different sizes on different systems")
    if words[0] == "struct" and len(words) == 2:
        if words[1] not in structs["tags"]:
            raise ValueError(f"struct {words[1]} is not defined before use")
        name = structs["tags"][words[1]]
    elif base in structs["aliases"]:
        name = base
    elif base in _BASE:
        name = _BASE[base]
    else:
        raise ValueError(f"unknown type: {c_type!r}")
    if stars == 0:
        return name
    special = {"None": "c_void_p", "c_char": "c_char_p", "c_wchar": "c_wchar_p"}
    if name in special:
        name = special[name]
        stars -= 1
    for _ in range(stars):
        name = f"POINTER({name})"
    return name


def _qualify(name):
    return re.sub(r"\b(c_\w+|POINTER)\b", r"ctypes.\1", name)


def _param_type(param):
    p = param.strip()
    if not p:
        raise ValueError("empty parameter")
    array = re.fullmatch(r"(.*?)\b([A-Za-z_]\w*)\s*\[\s*\d*\s*\]", p)
    if array:
        return array.group(1) + " *"
    tokens = re.findall(r"\w+|\*", p)
    if len(tokens) > 1 and _IDENT.fullmatch(tokens[-1]) and tokens[-1] not in _KEYWORDS and tokens[-2] != "struct":
        tokens = tokens[:-1]
    return " ".join(tokens)


def _prototype(text, structs):
    open_paren, close_paren = text.find("("), text.rfind(")")
    if open_paren < 0 or close_paren < open_paren or text[close_paren + 1:].strip():
        raise ValueError(f"not a declaration: {text!r}")
    head = text[:open_paren].replace("*", " * ").split()
    if len(head) < 2 or not _IDENT.fullmatch(head[-1]):
        raise ValueError(f"not a declaration: {text!r}")
    inside = text[open_paren + 1:close_paren].strip()
    params = [] if inside in ("", "void") else [_type(_param_type(p), structs) for p in inside.split(",")]
    return _type(" ".join(head[:-1]), structs), head[-1], params


def _field(text, structs):
    if "," in text:
        raise ValueError(f"one name per field, please: {text!r}")
    array = re.fullmatch(r"\s*(.+?)\b([A-Za-z_]\w*)\s*\[\s*(\d+)\s*\]\s*", text)
    if array:
        return array.group(2), f"{_qualify(_type(array.group(1), structs))} * {int(array.group(3))}"
    tokens = re.findall(r"\w+|\*", text)
    if len(tokens) < 2 or not _IDENT.fullmatch(tokens[-1]) or tokens[-1] in _KEYWORDS:
        raise ValueError(f"bad field: {text!r}")
    return tokens[-1], _qualify(_type(" ".join(tokens[:-1]), structs))


def generate_module(header, lib="lib"):
    text = re.sub(r"/\*.*?\*/", " ", header, flags=re.S)
    text = re.sub(r"//[^\n]*", "", text)
    text = re.sub(r"^\s*#[^\n]*", "", text, flags=re.M)
    structs = {"tags": {}, "aliases": set()}
    classes, functions = [], []

    def declarations(chunk):
        for statement in chunk.split(";"):
            statement = " ".join(statement.split())
            if statement:
                functions.append(_prototype(statement, structs))

    position = 0
    for m in _STRUCT.finditer(text):
        declarations(text[position:m.start()])
        position = m.end()
        is_typedef, tag, body, alias = m.group(1), m.group(2), m.group(3), m.group(4)
        if is_typedef and not alias:
            raise ValueError("typedef struct without an alias")
        if not is_typedef and alias:
            raise ValueError("struct variables are not supported")
        name = alias or tag
        if not name:
            raise ValueError("a struct needs a tag or an alias")
        fields = [_field(f, structs) for f in body.split(";") if f.strip()]
        if tag:
            structs["tags"][tag] = name
        structs["aliases"].add(name)
        classes.append((name, fields))
    declarations(text[position:])

    out = ["import ctypes", ""]
    for name, fields in classes:
        out.append("")
        out.append(f"class {name}(ctypes.Structure):")
        out.append("    _fields_ = [" + ", ".join(f'("{f}", {t})' for f, t in fields) + "]")
        out.append("")
    for restype, name, args in functions:
        out.append(f"{lib}.{name}.argtypes = [{', '.join(_qualify(a) for a in args)}]")
        out.append(f"{lib}.{name}.restype = {_qualify(restype)}")
    return "\n".join(out) + "\n"

