import ctypes
from types import SimpleNamespace

HEADER = """/* geometry.h - a small C library
   with structures and functions */
#pragma once
#include <stdint.h>

typedef struct point {
    int32_t x;   // across
    double y;
} point;

struct rect {
    struct point min;
    point max;
    uint8_t flags;
    char label[13];
    const char *note;
};

typedef struct {
    uint16_t id; uint16_t count;
    point corners[4];
} shape;

int32_t rect_area(const struct rect *r, double *out);
const char *geometry_version(void);
void shape_reset(shape *s, uint16_t id);
"""

class FakeLib:
    def __getattr__(self, name):
        value = SimpleNamespace()
        setattr(self, name, value)
        return value

def load(header, lib="lib"):
    source = generate_module(header, lib)
    namespace = {lib: FakeLib()}
    exec(source, namespace)
    return source, namespace

@test("the module starts with the import")
def _():
    source, _ns = load(HEADER)
    check(source.startswith("import ctypes"))

@test("structures have the C layout")
def _():
    _s, ns = load(HEADER)
    point, rect, shape = ns["point"], ns["rect"], ns["shape"]
    check_eq((ctypes.sizeof(point), point.x.offset, point.y.offset), (16, 0, 8))
    check_eq((ctypes.sizeof(rect), rect.min.offset, rect.max.offset, rect.flags.offset, rect.label.offset, rect.note.offset), (56, 0, 16, 32, 33, 48))
    check_eq((ctypes.sizeof(shape), shape.count.offset, shape.corners.offset), (72, 2, 8))
    r = rect()
    r.max.y = 2.5
    r.label = b"box"
    check_eq((r.max.y, r.label), (2.5, b"box"))

@test("field types")
def _():
    _s, ns = load(HEADER)
    fields = dict(ns["rect"]._fields_)
    check(fields["min"] is ns["point"] and fields["max"] is ns["point"])
    check(fields["note"] is ctypes.c_char_p)
    check_eq(ctypes.sizeof(fields["label"]), 13)
    check_eq(len(dict(ns["shape"]._fields_)["corners"]()), 4)

@test("functions")
def _():
    _s, ns = load(HEADER, lib="geo")
    geo = ns["geo"]
    check_eq(geo.rect_area.argtypes, [ctypes.POINTER(ns["rect"]), ctypes.POINTER(ctypes.c_double)])
    check(geo.rect_area.restype is ctypes.c_int32)
    check_eq(geo.geometry_version.argtypes, [])
    check(geo.geometry_version.restype is ctypes.c_char_p)
    check_eq(geo.shape_reset.argtypes, [ctypes.POINTER(ns["shape"]), ctypes.c_uint16])
    check(geo.shape_reset.restype is None)

@test("only declarations, only structures")
def _():
    _s, ns = load("double scale(double v, float f);")
    check_eq(ns["lib"].scale.argtypes, [ctypes.c_double, ctypes.c_float])
    _s, ns = load("struct empty_tail { int8_t a; int64_t b; };")
    check_eq(ctypes.sizeof(ns["empty_tail"]), 16)

@test("refusing what it cannot bind")
def _():
    bad = [
        "struct a { int x, y; };",
        "struct a { long x; };",
        "struct a { struct b inner; };",
        "typedef struct { int x; };",
        "struct { int x; };",
        "struct a { int x; } instance;",
        "int broken(;",
        "void uses(struct unknown *u);",
        "struct a { unknown_t x; };",
    ]
    for header in bad:
        check_raises(ValueError, generate_module, header)

